609	const clientStream = (
610	  client: WhatsAppClient
611	): ManagedStream<WhatsAppMessage> => {
612	  const eventStream = client.events
613	    .subscribe({
614	      // The client heals disconnects AND silently stalled streams on its own
615	      // (its stallTimeoutMs converts missed heartbeats into a reconnect with
616	      // cursor gap-fill). That recovery is invisible from out here, so
617	      // surface each attempt for operators — without this a stalled stream
618	      // heals with zero log evidence and a flapping upstream is
619	      // indistinguishable from a healthy one.
620	      reconnect: {
621	        onReconnect: (attempt) => {
622	          streamLog.warn("whatsapp live stream reconnecting", {
623	            "spectrum.whatsapp.reconnect_attempt": attempt,
624	          });
625	        },
626	      },
627	    })
628	    .filter(
629	      (e): e is Extract<typeof e, { type: "message" }> => e.type === "message"
630	    );
631	
632	  return stream<WhatsAppMessage>((emit, end) => {
633	    const pump = (async () => {
634	      try {
635	        for await (const event of eventStream) {
636	          // One unmappable event must not kill the live stream: a mapping
637	          // throw here ends the merged stream for the whole project, and
638	          // nothing downstream restarts it. Skip the event and keep pumping.
639	          let mapped: WhatsAppMessage[];
640	          try {
641	            mapped = toMessages(client, event.message);
642	          } catch (error) {
643	            streamLog.warn(
644	              "skipping unmappable whatsapp message event",
645	              {
646	                "spectrum.whatsapp.message_id": event.message.id,
647	                ...errorAttrs(error),
648	              },
649	              error instanceof Error ? error : undefined
650	            );
651	            continue;
652	          }
653	          for (const m of mapped) {
654	            await emit(m);
655	          }
656	        }
657	        end();
658	      } catch (e) {
659	        end(e);
660	      }
661	    })();
662	    return async () => {
663	      await eventStream.close();
664	      await pump;
665	    };
666	  });
667	};
