import { expect, test } from "bun:test";
import { markRead, uploadMedia } from "../src/meta/client";

async function captureMarkRead(typingIndicator?: boolean) {
  const originalFetch = globalThis.fetch;
  let captured: Request | undefined;
  globalThis.fetch = ((input: string | URL | Request, init?: RequestInit) => {
    captured = new Request(input, init);
    return Promise.resolve(Response.json({ success: true }));
  }) as typeof fetch;

  try {
    await markRead("test-token", "15550001111", "wamid.abc", typingIndicator);
  } finally {
    globalThis.fetch = originalFetch;
  }
  if (!captured) {
    throw new Error("fetch was never called");
  }
  return captured.json();
}

test("markRead sends a plain read receipt without typing_indicator", async () => {
  const body = await captureMarkRead();
  expect(body).toEqual({
    messaging_product: "whatsapp",
    status: "read",
    message_id: "wamid.abc",
  });
});

// Meta's typing API is a rider on mark-as-read — the request must carry
// typing_indicator.type = "text" (the only supported type) alongside the
// read receipt for the indicator to display.
test("markRead with typingIndicator adds typing_indicator to the body", async () => {
  const body = await captureMarkRead(true);
  expect(body).toEqual({
    messaging_product: "whatsapp",
    status: "read",
    message_id: "wamid.abc",
    typing_indicator: { type: "text" },
  });
});

