  getTrackedProjects,
  isProjectDisabled,
} from "./connection-registry.ts";
import { dropProjectLines } from "./dedicated-lines.ts";
import { fetchProjectPlatforms } from "./spectrum-cloud-client.ts";

let pollTimer: ReturnType<typeof setInterval> | undefined;
const inFlightRevalidations = new Map<string, Promise<boolean>>();

async function isVoiceEnabled(projectId: string): Promise<boolean> {
  const { data, error } = await fetchProjectPlatforms(projectId);
  if (error) {
    throw new Error(
      `spectrum-cloud platforms.get projectId=${projectId} status=${error.status}`
    );
  }
  return data?.voice?.enabled === true && data.voice?.imessage_enabled === true;
}

async function pollPlatforms(): Promise<void> {
  const projects = getTrackedProjects();
  if (projects.length === 0) {
    return;
  }
  const results = await Promise.allSettled(
    projects.map(async (projectId) => ({
      projectId,
      enabled: await isVoiceEnabled(projectId),
    }))
  );
  for (const result of results) {
    if (result.status === "rejected") {
      console.error("[platform-guard] check failed", result.reason);
      continue;
    }
    const { projectId, enabled } = result.value;
    const currentlyDisabled = isProjectDisabled(projectId);
    if (!(enabled || currentlyDisabled)) {
      console.log(
        `[platform-guard] disabling project=${projectId} — voice gate closed`
      );
      disconnectProject(projectId);
      dropProjectLines(projectId);
    } else if (enabled && currentlyDisabled) {
      console.log(`[platform-guard] re-enabling project=${projectId}`);
      enableProject(projectId);
    }
  }
}

export function revalidateProject(projectId: string): Promise<boolean> {
  const pending = inFlightRevalidations.get(projectId);
  if (pending) {
    return pending;
  }
  const promise = (async () => {
    try {
      const enabled = await isVoiceEnabled(projectId);
      if (enabled) {
        enableProject(projectId);
      }
      return enabled;
    } catch (err) {
      console.error(
        `[platform-guard] revalidate threw, failing open project=${projectId}`,
        err
      );
      return true;
    }
  })().finally(() => {
    inFlightRevalidations.delete(projectId);
  });
  inFlightRevalidations.set(projectId, promise);
  return promise;
}

export async function startPlatformGuard(): Promise<void> {
  await pollPlatforms();
  pollTimer = setInterval(pollPlatforms, config.cloud.platformPollIntervalMs);
}

export function stopPlatformGuard(): void {
  if (pollTimer) {
    clearInterval(pollTimer);
    pollTimer = undefined;
  }
}

