const MAX_INBOUND_WAMID_CACHE_SIZE = 1000;
const inboundWamidCaches = new WeakMap<WhatsAppClient, Map<string, string>>();

const rememberInboundWamid = (
  client: WhatsAppClient,
  spaceId: string,
